# CHS capacity calculator + classic format decoder (public-domain math)

def chs_capacity(cylinders, heads, sectors, bps=512):
    total_sectors = cylinders * heads * sectors
    total_bytes = total_sectors * bps
    return {"sectors": total_sectors,
            "bytes": total_bytes,
            "KB": round(total_bytes / 1024, 1),
            "MB": round(total_bytes / 1024 / 1024, 3)}

FORMATS = {
    "8in SSSD (IBM 3740)": (77, 1, 26, 128),
    "5.25in 360K DD": (40, 2, 9, 512),
    "5.25in 1.2M HD": (80, 2, 15, 512),
    "3.5in 720K DD": (80, 2, 9, 512),
    "3.5in 1.44M HD": (80, 2, 18, 512),
    "3.5in 2.88M ED": (80, 2, 36, 512),
    "ST-506 5MB": (153, 4, 32, 256),
    "IBM 2311 (1964)": (200, 10, 20, 7294//20),
}
for name, geo in FORMATS.items():
    r = chs_capacity(*geo)
    print(f"{name:22s} -> {r['KB']:>9} KB  ({r['sectors']} sectors)")

# LBA from CHS (what IDE did under the hood)
def chs_to_lba(c, h, s, heads, spt):
    return (c * heads + h) * spt + (s - 1)
print("\nCHS(79,1,18) on 1.44M floppy -> LBA", chs_to_lba(79, 1, 18, 2, 18))
